const negotiationTerms = ['orçamento', 'orcamento', 'preço', 'preco', 'prazo', 'contrato', 'proposta', 'reunião', 'reuniao', 'fechar', 'escopo', 'valor', 'disponibilidade', 'interesse'];

return $input.all().map(({ json }) => {
  const text = [json.subject, json.snippet, json.textPlain, json.text].filter(Boolean).join(' ').toLocaleLowerCase('pt-BR');
  const matchedTerms = negotiationTerms.filter((term) => text.includes(term));
  return {
    json: {
      ...json,
      negotiation_signal: matchedTerms.length > 0,
      matched_terms: matchedTerms,
      alert_subject: `Oportunidade de negociação: ${json.subject || 'nova resposta por e-mail'}`
    }
  };
}).filter(({ json }) => json.negotiation_signal);
